import openpyxl, re
wb = openpyxl.load_workbook('extraction/providence-worcester.xlsx')
ws = wb['Questions']
for r in range(2, ws.max_row+1):
    if ws.cell(r,1).value == 'Q4':
        ws.cell(r,3).value = "Yes, flagged. On 08/04 the Committee moved to complete the agreement with B and B's counsel returned a revised draft; B's LOI sat in a Not final round."
        ws.cell(r,6).value = "Without it, B's last priced row is the round-2 LOI, already Formal; #51 shows B stood there."
wb.save('extraction/providence-worcester.xlsx')

# ---- full verification ----
wb = openpyxl.load_workbook('extraction/providence-worcester.xlsx')
ws = wb['Questions']; led = wb['Deal ledger']
flags = {}
for r in range(2, led.max_row+1):
    n = led.cell(r,1).value
    f = led.cell(r,18).value
    flags[n] = set(x.strip() for x in str(f).split(';')) if f else set()

def expand(s):
    out=[]
    for part in str(s).split(','):
        part=part.strip().lstrip('#')
        m=re.match(r'^(\d+)-#?(\d+)$', part)
        if m: out += list(range(int(m.group(1)), int(m.group(2))+1))
        elif part.isdigit(): out.append(int(part))
        else: print('UNPARSED', part)
    return out

print('word counts + cross-check')
ok=True
cited={}
for r in range(2, ws.max_row+1):
    q = ws.cell(r,1).value
    tot = sum(len(str(ws.cell(r,c).value).split()) for c in range(2,7) if ws.cell(r,c).value)
    rows = expand(ws.cell(r,5).value)
    for n in rows:
        cited.setdefault(n,set()).add(q)
        if q not in flags.get(n,set()):
            print(f'  MISMATCH: {q} cites #{n} but flag={flags.get(n)}'); ok=False
    print(f'  {q}: {tot} words, cites {rows}')
for n,fs in flags.items():
    for f in fs:
        if f and q_missing := (f not in cited.get(n,set())):
            print(f'  MISMATCH: #{n} flagged {f} but {f} does not cite it'); ok=False
print('consistent:', ok)
PYEOF

